INSERT dbo.users (username, password_hash)
SELECT d.username, d.password_hash
FROM OPENJSON(@json) WITH (
        username      NVARCHAR(256) N'$.username',
        password_hash NVARCHAR(512) N'$.password_hash'
     ) AS d
