-- standee.json — 3 document(s), 1119 chars of JSON
SET @json = N'';
SET @json += N'[{"standee_type":"Simple Standee","cutting_die_blank_form_min":1400,"cutting_die_inches_multiplier":1,"cutting_die_print_form_min":1200,"engineering_design_cost_per_project":300,"hardware_cost":2.5,"instruction_sheet_engineering_cost_per_project":300,"instruction_sheet_total_cost":1.2,"kitting_and_assembly":375,"zund_blank_form_minutes":12,"zund_print_form_minutes":15},{"standee_type":"Moderate Standee","cutting_die_blank_form_min":1700,"cutting_die_inches_multiplier":1.5,"cutting_die_print_form_min":1500,"engineering_design_cost_per_project":500,"hardware_cost":7.5,"instruction_sheet_engineering_cost_per_project":500,"instruction_sheet_total_cost":1.6,"kitting_and_assembly":750,"zund_blank_form_minutes":15,"zund_print_form_minutes":18},{"standee_type":"Complex Standee","cutting_die_blank_form_min":2000,"cutting_die_inches_multiplier":2,"cutting_die_print_form_min":1800,"engineering_design_cost_per_project":700,"hardware_cost":15,"instruction_sheet_engineering_cost_per_project":700,"instruction_sheet_total_cost":2.4,"kitting_and_assembly":1125,"zund_blank_form_minutes":20,"zund_print_form_minutes":25}]';
IF ISJSON(@json) <> 1 THROW 50002, N'Embedded JSON for standee.json is corrupt — the script was edited or truncated.', 1;

INSERT dbo.standee_static_costs (
        standee_type, engineering_design_cost_per_project,
        instruction_sheet_engineering_cost_per_project, hardware_cost,
        zund_print_form_minutes, zund_blank_form_minutes, instruction_sheet_total_cost,
        cutting_die_inches_multiplier, kitting_and_assembly,
        cutting_die_blank_form_min, cutting_die_print_form_min)
SELECT
    d.standee_type, d.engineering_design_cost_per_project,
    d.instruction_sheet_engineering_cost_per_project, d.hardware_cost,
    d.zund_print_form_minutes, d.zund_blank_form_minutes, d.instruction_sheet_total_cost,
    d.cutting_die_inches_multiplier, d.kitting_and_assembly,
    d.cutting_die_blank_form_min, d.cutting_die_print_form_min
FROM OPENJSON(@json) WITH (
        standee_type                                   NVARCHAR(64) N'$.standee_type',
        engineering_design_cost_per_project            FLOAT N'$.engineering_design_cost_per_project',
        instruction_sheet_engineering_cost_per_project FLOAT N'$.instruction_sheet_engineering_cost_per_project',
        hardware_cost                                  FLOAT N'$.hardware_cost',
        zund_print_form_minutes                        FLOAT N'$.zund_print_form_minutes',
        zund_blank_form_minutes                        FLOAT N'$.zund_blank_form_minutes',
        instruction_sheet_total_cost                   FLOAT N'$.instruction_sheet_total_cost',
        cutting_die_inches_multiplier                  FLOAT N'$.cutting_die_inches_multiplier',
        kitting_and_assembly                           FLOAT N'$.kitting_and_assembly',
        cutting_die_blank_form_min                     FLOAT N'$.cutting_die_blank_form_min',
        cutting_die_print_form_min                     FLOAT N'$.cutting_die_print_form_min'
     ) AS d
WHERE NOT EXISTS (
        SELECT 1 FROM dbo.standee_static_costs s WHERE s.standee_type = d.standee_type);

-- ───────────────────────── print_blank_ratio ───────────────────────
-- print_blank.json — 10 document(s), 354 chars of JSON
SET @json = N'';
SET @json += N'[{"print_forms":3,"blank_forms":4.5},{"print_forms":4,"blank_forms":6},{"print_forms":5,"blank_forms":7.5},{"print_forms":6,"blank_forms":9},{"print_forms":7,"blank_forms":10.5},{"print_forms":8,"blank_forms":12},{"print_forms":9,"blank_forms":13.5},{"print_forms":10,"blank_forms":15},{"print_forms":1,"blank_forms":2},{"print_forms":2,"blank_forms":4}]';
IF ISJSON(@json) <> 1 THROW 50002, N'Embedded JSON for print_blank.json is corrupt — the script was edited or truncated.', 1;

INSERT dbo.print_blank_ratio (print_forms, blank_forms)
SELECT d.print_forms, d.blank_forms
FROM OPENJSON(@json) WITH (
        print_forms INT   N'$.print_forms',
        blank_forms FLOAT N'$.blank_forms'
     ) AS d
WHERE NOT EXISTS (
        SELECT 1 FROM dbo.print_blank_ratio r WHERE r.print_forms = d.print_forms);

-- ─────────────────────────────── overs ─────────────────────────────
-- overs.json — 4 document(s), 192 chars of JSON
SET @json = N'';
SET @json += N'[{"lower_bound":1,"upper_bound":10,"overs":3},{"lower_bound":10,"upper_bound":50,"overs":10},{"lower_bound":50,"upper_bound":200,"overs":25},{"lower_bound":200,"upper_bound":null,"overs":100}]';
IF ISJSON(@json) <> 1 THROW 50002, N'Embedded JSON for overs.json is corrupt — the script was edited or truncated.', 1;

-- No unique constraint on overs, so the tier bounds act as the natural key
-- (upper_bound is NULL on the open-ended top tier — hence the IS NULL arm).
INSERT dbo.overs (lower_bound, upper_bound, overs)
SELECT d.lower_bound, d.upper_bound, d.overs
FROM OPENJSON(@json) WITH (
        lower_bound INT N'$.lower_bound',
        upper_bound INT N'$.upper_bound',
        overs       INT N'$.overs'
     ) AS d
WHERE NOT EXISTS (
        SELECT 1 FROM dbo.overs o
        WHERE o.lower_bound = d.lower_bound
          AND (o.upper_bound = d.upper_bound
               OR (o.upper_bound IS NULL AND d.upper_bound IS NULL)));

-- ────────────────────────────── packout ────────────────────────────
-- packout.json — 21 document(s), 1921 chars of JSON
SET @json = N'';
SET @json += N'[{"standees_lower_bound":1,"standees_upper_bound":10,"complexity":"Simple","packout":75},{"standees_lower_bound":1,"standees_upper_bound":10,"complexity":"Moderate","packout":150},{"standees_lower_bound":1,"standees_upper_bound":10,"complexity":"Complex","packout":250},{"standees_lower_bound":11,"standees_upper_bound":25,"complexity":"Simple","packout":65},{"standees_lower_bound":11,"standees_upper_bound":25,"complexity":"Moderate","packout":135},{"standees_lower_bound":11,"standees_upper_bound":25,"complexity":"Complex","packout":225},{"standees_lower_bound":26,"standees_upper_bound":50,"complexity":"Simple","packout":55},{"standees_lower_bound":26,"standees_upper_bound":50,"complexity":"Moderate","packout":115},{"standees_lower_bound":26,"standees_upper_bound":50,"complexity":"Complex","packout":190},{"standees_lower_bound":51,"standees_upper_bound":100,"complexity":"Simple","packout":45},{"standees_lower_bound":51,"standees_upper_bound":100,"complexity":"Moderate","packout":95},{"standees_lower_bound":51,"standees_upper_bound":100,"complexity":"Complex","packout":155}';
SET @json += N',{"standees_lower_bound":101,"standees_upper_bound":250,"complexity":"Simple","packout":35},{"standees_lower_bound":101,"standees_upper_bound":250,"complexity":"Moderate","packout":75},{"standees_lower_bound":101,"standees_upper_bound":250,"complexity":"Complex","packout":120},{"standees_lower_bound":251,"standees_upper_bound":500,"complexity":"Simple","packout":30},{"standees_lower_bound":251,"standees_upper_bound":500,"complexity":"Moderate","packout":65},{"standees_lower_bound":251,"standees_upper_bound":500,"complexity":"Complex","packout":100},{"standees_lower_bound":501,"standees_upper_bound":null,"complexity":"Simple","packout":25},{"standees_lower_bound":501,"standees_upper_bound":null,"complexity":"Moderate","packout":55},{"standees_lower_bound":501,"standees_upper_bound":null,"complexity":"Complex","packout":85}]';
IF ISJSON(@json) <> 1 THROW 50002, N'Embedded JSON for packout.json is corrupt — the script was edited or truncated.', 1;

-- One row per (standees range, complexity) — packout no longer varies by a
-- forms range (see create_tables.sql).
INSERT dbo.packout (standees_lower_bound, standees_upper_bound, complexity, packout, last_updated)
SELECT d.standees_lower_bound, d.standees_upper_bound, d.complexity, d.packout,
       ISNULL(TRY_CONVERT(DATETIME2(3), d.last_updated, 127), SYSUTCDATETIME())
FROM OPENJSON(@json) WITH (
        standees_lower_bound INT          N'$.standees_lower_bound',
        standees_upper_bound INT          N'$.standees_upper_bound',
        complexity           NVARCHAR(32) N'$.complexity',
        packout               FLOAT        N'$.packout',
        last_updated          NVARCHAR(64) N'$.last_updated'  -- absent on most rows
     ) AS d
WHERE NOT EXISTS (
        SELECT 1 FROM dbo.packout p
        WHERE p.complexity = d.complexity
          AND p.standees_lower_bound = d.standees_lower_bound
          AND (p.standees_upper_bound = d.standees_upper_bound
               OR (p.standees_upper_bound IS NULL AND d.standees_upper_bound IS NULL)));

